from decimal import Decimal, ROUND_HALF_UP, localcontext


_CENTS = Decimal("0.01")


def _amount(value) -> Decimal:
    """Apply legacy NVL numeric coercion and NUMBER(15,2) half-up rounding."""
    if value is None or value == "":
        return Decimal("0.00")

    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Decimal("0.00")

    with localcontext() as context:
        context.prec = 50
        return Decimal(str(value)).quantize(_CENTS, rounding=ROUND_HALF_UP)


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    new_accounts = [dict(account) for account in accounts]
    audits = []

    eligible_indexes = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]

    for index in sorted(eligible_indexes, key=lambda i: new_accounts[i].get("ACCT_ID", "")):
        account = new_accounts[index]
        acct_id = account.get("ACCT_ID")

        exposure = Decimal("0.00")
        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _amount(order.get("TOT_AMT"))

        credit_limit = _amount(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * Decimal(8) / Decimal(10) and account.get("CRED_HOLD") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
